import{_ as s,o as a,c as t,ao as i}from"./chunks/framework.D7TN4pt9.js";const m=JSON.parse('{"title":"Agents messaging each other","description":"","frontmatter":{},"headers":[],"relativePath":"guide/messaging.md","filePath":"guide/messaging.md","lastUpdated":null}'),n={name:"guide/messaging.md"};function o(h,e,r,l,d,c){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="Agents-messaging-each-other" tabindex="-1">Agents messaging each other <a class="header-anchor" href="#Agents-messaging-each-other" aria-label="Permalink to &quot;Agents messaging each other {#Agents-messaging-each-other}&quot;">​</a></h1><p>Sessions talk to each other. An agent working on your package can ask the agent working on its dependency a question, a worktree session can report back to its parent, and a session on a GPU server can tell the one on your laptop that a run finished. This is the <strong>comm relay</strong>; the agents use it through the bundled skills. You can use the same scripts from a shell that has joined (a row&#39;s own shell has; the Terminal drawer or a bare terminal has not, and a send from there is refused).</p><h2 id="Every-session-joins-at-start" tabindex="-1">Every session joins at start <a class="header-anchor" href="#Every-session-joins-at-start" aria-label="Permalink to &quot;Every session joins at start {#Every-session-joins-at-start}&quot;">​</a></h2><p>A Claude Code session created in Sessions mode runs <code>/sot-session-start</code> once; a Codex row is joined by its launcher. Either way the session joins the registry under a <strong>handle</strong>, made from its folder and box name; <code>comm-list.sh</code> prints the exact string. From then on the session is addressable as <code>@&lt;handle&gt;</code> from any other session, on any connected host.</p><h2 id="Ask,-tell,-broadcast" tabindex="-1">Ask, tell, broadcast <a class="header-anchor" href="#Ask,-tell,-broadcast" aria-label="Permalink to &quot;Ask, tell, broadcast {#Ask,-tell,-broadcast}&quot;">​</a></h2><p>The agents call these for you when you say &quot;ask the kernel session whether…&quot;, but they are plain scripts in <code>~/.sot-comm/bin</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comm-list.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                 # who is reachable, and their state</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comm-send.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @other-session</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;message&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # one result: filed, or FAILED with the reason</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comm-send.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --broadcast</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;message&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # filed to every live session, one result each</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comm-send.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @other-session</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> notes.md</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # the body is the file&#39;s bytes: quotes and $( ) arrive as written</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comm-poll.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                 # read what has arrived</span></span></code></pre></div><p>Quote the message in single quotes: inside double quotes the shell runs backquotes and <code>$( )</code> in it as commands before the send.</p><p>A send appends one line to the recipient&#39;s inbox (<code>~/.sot-comm/inbox/&lt;handle&gt;.jsonl</code>) and prints <code>filed -&gt; @handle</code>. It fails, and files nothing, when no live session holds the handle. The recipient reads it with <code>comm-poll.sh</code>.</p><h2 id="A-message-wakes-the-recipient" tabindex="-1">A message wakes the recipient <a class="header-anchor" href="#A-message-wakes-the-recipient" aria-label="Permalink to &quot;A message wakes the recipient {#A-message-wakes-the-recipient}&quot;">​</a></h2><p>An idle Claude Code session does not have to be polling. When a directed message is filed for a session sitting at a free prompt, the daemon types one fixed line into its row (<code>[sot-comm] you have mail: run comm-poll.sh</code>), and the session reads the messages itself with <code>comm-poll.sh</code>, so a burst of messages costs one wake. The wake is refused while the row shows a permission dialog or a menu, so it can never answer one by accident. A Codex session is not woken: it sees mail when it runs <code>comm-poll.sh</code>. A broadcast wakes nobody.</p><h2 id="What-travels-with-it" tabindex="-1">What travels with it <a class="header-anchor" href="#What-travels-with-it" aria-label="Permalink to &quot;What travels with it {#What-travels-with-it}&quot;">​</a></h2><p>The same registry that routes messages carries each session&#39;s work state (working, blocked, waiting, done, idle), which is what colors the rows in Sessions mode. See <a href="./../concepts/work-state">Work-state colors</a> and, for the wire format and the registry layout, <a href="./../concepts/comm">The comm relay</a> and the <a href="./../ref/comm">Comm protocol</a> reference.</p>`,13)])])}const g=s(n,[["render",o]]);export{m as __pageData,g as default};
